command:
set -eu; mkdir -p /tmp/conversion /tmp/context /tmp/rootfs /tmp/check; printf '%s\n' 'FROM localhost/pinfold/local:latest' > /tmp/conversion/Dockerfile; buildctl build --frontend dockerfile.v0 --local context=/tmp/context --local dockerfile=/tmp/conversion --oci-layout localbase=/input --opt context:localhost/pinfold/local=oci-layout://localbase@sha256:871f87c0b192a668ac95bfe54d8e13b1ab1091cd3eade32182688fddb6e2769b --output type=tar,dest=/tmp/root.tar; tar -tvf /tmp/root.tar; tar --numeric-owner --xattrs --xattrs-include='*' -xpf /tmp/root.tar -C /tmp/rootfs; printf %s 'import json,os,stat,sys
from pathlib import Path
p=Path(sys.argv[1]);s=(p/"owned").stat();h=(p/"hard").stat()
r={"uid":s.st_uid,"gid":s.st_gid,"mode":oct(stat.S_IMODE(s.st_mode)),"hardlink":s.st_ino==h.st_ino,"symlink":os.readlink(p/"sym"),"gone":(p/"gone").exists(),"old":(p/"dir/old").exists(),"new":(p/"dir/new").read_text(),"xattrs":os.listxattr(p/"owned")}
try:r["user.phase6"]=os.getxattr(p/"owned","user.phase6").decode()
except OSError as e:r["xattr_error"]=str(e)
print(json.dumps(r))
assert (r["uid"],r["gid"],r["mode"],r["hardlink"],r["symlink"],r["gone"],r["old"],r["new"])==(123,456,"0o751",True,"/owned",False,False,"newer\n")
assert r.get("user.phase6")=="yes"
' >/tmp/check.py; python3 /tmp/check.py /tmp/rootfs; mkdir -p /tmp/rootfs/proc /tmp/rootfs/dev; truncate -s 128M /var/lib/buildkit/converted.ext4; mkfs.ext4 -q -F -m 0 -O ^has_journal -d /tmp/rootfs /var/lib/buildkit/converted.ext4; mount -o loop,ro /var/lib/buildkit/converted.ext4 /tmp/check; python3 /tmp/check.py /tmp/check; umount /tmp/check; sync
